SELECT DATABASE() AS target_database, @@hostname AS mysql_host, @@version AS mysql_version, NOW() AS inspected_at;
SELECT a.id,a.accountNo,a.accountName,a.accountType,a.financialStatement,a.naturalBalance,a.parentId,a.isActive,COUNT(l.id) AS journal_lines,COALESCE(SUM(l.debitAmount),0) AS debit,COALESCE(SUM(l.creditAmount),0) AS credit FROM chart_of_accounts a LEFT JOIN journal_entry_lines l ON l.chartOfAccountId=a.id GROUP BY a.id ORDER BY a.accountNo;
SELECT j.status,j.currencyId,COUNT(DISTINCT j.id) AS journals,COUNT(l.id) AS line_count,SUM(l.debitAmount) AS debit,SUM(l.creditAmount) AS credit FROM journal_entries j JOIN journal_entry_lines l ON l.journalEntryId=j.id GROUP BY j.status,j.currencyId;
SELECT TABLE_NAME,COLUMN_NAME,REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_NAME IN ('chart_of_accounts','journal_entries','journal_entry_lines','entity_chart_of_accounts') ORDER BY TABLE_NAME,COLUMN_NAME;
SELECT TABLE_NAME,COLUMN_NAME,DATA_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND (LOWER(COLUMN_NAME) REGEXP 'account|ledger|snapshot|balance|report|cache' OR DATA_TYPE='json') ORDER BY TABLE_NAME,ORDINAL_POSITION;
SELECT TABLE_NAME,TABLE_TYPE,ENGINE,TABLE_ROWS FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() ORDER BY TABLE_NAME;
SELECT a.accountNo,j.status,j.description AS journal_purpose,l.description AS line_purpose,COUNT(*) AS line_count,SUM(l.debitAmount) AS debit,SUM(l.creditAmount) AS credit FROM journal_entry_lines l JOIN chart_of_accounts a ON a.id=l.chartOfAccountId JOIN journal_entries j ON j.id=l.journalEntryId GROUP BY a.accountNo,j.status,j.description,l.description ORDER BY a.accountNo,line_count DESC LIMIT 100;
SELECT TABLE_NAME,VIEW_DEFINITION FROM information_schema.VIEWS WHERE TABLE_SCHEMA=DATABASE();
SELECT TRIGGER_NAME,EVENT_OBJECT_TABLE,ACTION_STATEMENT FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE();
